import numpy as np, json
dir7='/work/fwd_7'
meta=json.load(open(dir7+'/meta.json'))
lengths=meta['lengths']; token_ids=meta['token_ids']
WAIT=13784; THINK=248069
for L in ['8','16','24']:
    H=np.load(dir7+f'/hidden_L{L}.npy').astype(np.float32)
    loop=[]; close=[]; other=[]
    for t,(ids,Ln) in enumerate(zip(token_ids,lengths)):
        for p in range(Ln-1):
            nid=ids[p+1]
            if nid==WAIT: loop.append(H[t,p])
            elif nid==THINK: close.append(H[t,p])
            else: other.append(H[t,p])
    loop=np.array(loop); close=np.array(close); other=np.array(other)
    d=(loop.mean(0)-other.mean(0)); d=d/np.linalg.norm(d)
    emb=load_original('model.language_model.embed_tokens.weight').float().numpy()
    gamma=load_original('model.language_model.norm.weight').float().numpy()
    def cos(a,T):
        r=emb[T]*(1+gamma); return float(a@ (r/np.linalg.norm(r)))
    print(f'L{L}: |loop| {np.linalg.norm(loop.mean(0)):.1f} |other| {np.linalg.norm(other.mean(0)):.1f} |close| {np.linalg.norm(close.mean(0)):.1f}  nclose {len(close)}')
    print('   cos(d, Wait)', round(cos(d,WAIT),3), 'cos(d, think)', round(cos(d,THINK),3))
    np.save(f'/work/loop_dir_L{L}.npy', d)
